<script setup>
import { ref, shallowRef, computed, watch } from 'vue'
import ExcelJS from 'exceljs'
const book=shallowRef(null), sheetId=ref(''), filename=ref(''), busy=ref(false), error=ref(''), result=shallowRef(null)
const columns=ref([]), whitespace=ref('none'), replaceCol=ref(''), find=ref(''), replacement=ref(''), exact=ref(true), blankRows=ref(false), zeroCol=ref(''), serial=ref(false)
const sheet=computed(()=>book.value?.getWorksheet(Number(sheetId.value)))
const headers=computed(()=>{const s=sheet.value; if(!s)return [];return Array.from({length:s.columnCount},(_,i)=>({id:i+1,name:s.getRow(1).getCell(i+1).text||`欄 ${i+1}`}))})
watch([sheetId,columns,whitespace,replaceCol,find,replacement,exact,blankRows,zeroCol,serial],()=>{result.value=null},{deep:true,flush:'sync'})
watch(sheetId,()=>{columns.value=[];replaceCol.value='';zeroCol.value=''},{flush:'sync'})
const show=v=>v instanceof Date?v.toISOString().slice(0,10):v==null?'':String(v)
const empty=v=>v==null||(typeof v==='string'&&!v.trim())
function readCell(c){let v=c.value;if(v&&typeof v==='object'&&!(v instanceof Date)){if('formula' in v||'sharedFormula' in v){if(v.result===undefined||v.result===null)throw new Error(`儲存格 ${c.address} 的公式沒有快取結果，請先用 Excel 重新計算並儲存。`);v=v.result}if(v&&typeof v==='object'&&!(v instanceof Date)){v=c.text}}return {v,fmt:c.numFmt}}
async function upload(e){const f=e.target.files?.[0];e.target.value='';if(!f)return;busy.value=true;error.value='';result.value=null;book.value=null;sheetId.value='';try{if(!/\.xlsx$/i.test(f.name)||f.size>20*1024*1024)throw new Error('請選擇 20 MB 以內的 .xlsx 檔案。');const b=new ExcelJS.Workbook();await b.xlsx.load(await f.arrayBuffer());if(!b.worksheets.length)throw new Error('找不到工作表');book.value=b;filename.value=f.name;sheetId.value=String(b.worksheets[0].id)}catch(e){error.value=e.message}finally{busy.value=false}}
function clean(){error.value='';result.value=null;try{const s=sheet.value;if(!s)throw new Error('請先上傳檔案');if(s.rowCount>50001||s.columnCount>200||s.rowCount*s.columnCount>1000000)throw new Error('工作表超過本版處理上限（5 萬筆、200 欄、100 萬格）。');if(!s.columnCount)throw new Error('工作表沒有資料');if(whitespace.value!=='none'&&!columns.value.length)throw new Error('請選取要移除空格的欄位');if(replaceCol.value&&!find.value)throw new Error('請輸入要尋找的文字');const head=headers.value.map(h=>({v:h.name}));if(serial.value&&head.some(c=>c.v==='流水編號'))throw new Error('原表已有流水編號欄，請取消新增流水編號。');let changed=0,deleted=0;const rows=[];for(let r=2;r<=s.rowCount;r++){const row=Array.from({length:s.columnCount},(_,i)=>readCell(s.getRow(r).getCell(i+1)));row.forEach((cell,i)=>{const old=cell.v;if(typeof old==='string'&&columns.value.includes(i+1)){if(whitespace.value==='all')cell.v=old.replace(/\s/g,'');if(whitespace.value==='trim')cell.v=old.trim()}if(Number(replaceCol.value)===i+1){if(exact.value&&show(cell.v)===find.value){cell.v=typeof old==='number'&&replacement.value.trim()!==''&&Number.isFinite(Number(replacement.value))?Number(replacement.value):replacement.value}else if(!exact.value&&typeof cell.v==='string')cell.v=cell.v.split(find.value).join(replacement.value)}if(cell.v!==old)changed++});const z=zeroCol.value?row[Number(zeroCol.value)-1]?.v:null;if((blankRows.value&&row.every(c=>empty(c.v)))||(zeroCol.value&&(z===0||(typeof z==='string'&&z.trim()!==''&&Number(z)===0)))){deleted++;continue}if(serial.value)row.unshift({v:rows.length+1});rows.push(row)}if(serial.value)head.unshift({v:'流水編號'});result.value={head,rows,changed,deleted,original:s.rowCount-1,name:s.name}}catch(e){error.value=e.message}}
async function download(){const data=result.value;if(!data)return;busy.value=true;error.value='';try{const b=new ExcelJS.Workbook(),s=b.addWorksheet(data.name);s.addRow(data.head.map(c=>c.v));s.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};s.getRow(1).eachCell(c=>{c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF166534'}}});for(const row of data.rows){const rr=s.addRow(row.map(c=>c.v));row.forEach((c,i)=>{if(c.fmt)rr.getCell(i+1).numFmt=c.fmt})}s.columns.forEach(c=>{c.width=20});s.views=[{state:'frozen',ySplit:1}];s.autoFilter={from:{row:1,column:1},to:{row:1,column:data.head.length}};const buf=await b.xlsx.writeBuffer();const url=URL.createObjectURL(new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download=filename.value.replace(/\.xlsx$/i,'')+'_clean.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template>
<section class="ec"><h2>Excel 資料清理工作室</h2><p>以第一列為欄名，清理指定工作表並另存新檔。</p><p class="ec-note">輸出僅包含選定工作表的資料與基本數字格式；公式轉為快取值，不保留原圖表、合併儲存格及完整排版。原檔不變。</p>
<label>上傳 Excel (.xlsx)<input type="file" accept=".xlsx" :disabled="busy" @change="upload"></label>
<fieldset :disabled="busy||!book"><label>工作表<select v-model="sheetId"><option v-for="s in book?.worksheets||[]" :key="s.id" :value="String(s.id)">{{s.name}}</option></select></label>
<div class="ec-grid"><div class="ec-box"><h3>空格清理</h3><select v-model="whitespace"><option value="none">不處理</option><option value="trim">移除前後空格</option><option value="all">移除所有空白字元</option></select><label v-for="h in headers" :key="h.id" class="ec-check"><input type="checkbox" v-model="columns" :value="h.id">{{h.name}}</label></div><div class="ec-box"><h3>文字或數值取代</h3><label>指定欄位<select v-model="replaceCol"><option value="">不處理</option><option v-for="h in headers" :key="h.id" :value="String(h.id)">{{h.name}}</option></select></label><label>尋找<input v-model="find"></label><label>取代為<input v-model="replacement"></label><label class="ec-check"><input type="checkbox" v-model="exact">整格完全符合（數值取代請選此項）</label></div><div class="ec-box"><h3>列與編號</h3><label class="ec-check"><input type="checkbox" v-model="blankRows">刪除完全空白列</label><label>刪除數值為 0 的列<select v-model="zeroCol"><option value="">不處理</option><option v-for="h in headers" :key="h.id" :value="String(h.id)">{{h.name}}</option></select></label><label class="ec-check"><input type="checkbox" v-model="serial">新增流水編號</label></div></div><button type="button" @click="clean">執行清理並預覽</button></fieldset>
<p v-if="error" role="alert" class="ec-error">{{error}}</p><p v-if="busy">處理中…</p><template v-if="result"><div class="ec-stats">原始 {{result.original}} 筆｜保留 {{result.rows.length}} 筆｜刪除 {{result.deleted}} 筆｜修改 {{result.changed}} 格（含刪除列中的修改）</div><div class="ec-table"><table><thead><tr><th v-for="(h,i) in result.head" :key="i">{{h.v}}</th></tr></thead><tbody><tr v-for="(row,i) in result.rows.slice(0,30)" :key="i"><td v-for="(c,j) in row" :key="j">{{show(c.v)}}</td></tr></tbody></table></div><p>預覽前 30 筆，下載包含全部保留資料。</p><button :disabled="busy" @click="download">下載清理後 Excel</button></template></section>
</template>
<style scoped>
.ec{background:white;border-radius:20px;padding:20px;color:#18374a}.ec h3{font-size:1.1rem;color:#166534}.ec label{display:grid;gap:5px;margin:9px 0}.ec input:not([type=checkbox]),.ec select{width:100%;padding:9px;border:1px solid #a7c6b0;border-radius:8px;background:white;color:#18374a}.ec fieldset{border:0;padding:0;min-width:0}.ec-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin:14px 0}.ec-box{background:#f0fdf4;border-radius:14px;padding:14px;max-height:350px;overflow:auto}.ec .ec-check{display:flex;align-items:center;gap:8px}.ec button{background:#166534;color:white}.ec button:disabled{opacity:.5}.ec-note,.ec-stats{padding:12px;background:#dcfce7;border-radius:10px}.ec-error{color:#b91c1c}.ec-table{overflow:auto;max-height:420px}.ec table{border-collapse:collapse;width:100%}.ec th,.ec td{border:1px solid #cbd5e1;padding:8px;white-space:nowrap}.ec th{background:#166534;color:white;position:sticky;top:0}
</style>
